pub fn unset(self: *Tabstops, col: usize) void — Unset the tabstop at a certain column. The columns are 0-indexed.
pub fn get(self: Tabstops, col: usize) bool — Get the value of a tabstop at a specific column. The columns are 0-indexed.
pub fn resize(self: *Tabstops, alloc: Allocator, cols: usize) Allocator.Error!void
pub fn capacity(self: Tabstops) usize — Return the maximum number of columns this can support currently.
pub fn reset(self: *Tabstops, interval: usize) void — Unset all tabstops and then reset the initial tabstops to the given interval. An interval of 0 sets no tabstops.

